        5,
        9,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §20</em> <small>(c. 350 AD)</small><p>&#x27;And they sung a new song, saying, Thou art worthy to take the book, and to open the seals thereof: for thou wast slain, and hast redeemed us to God by thy blood out of every kindred, and tongue, and people, and nation&#x27; — Athanasius marks axios ei labein to biblion... hoti esphagēs kai ēgorasas tō theō en tō haimati sou (thou art WORTHY to take the book... for thou wast slain and hast purchased to God by thy blood) as the APOCALYPTIC REDEMPTION-BY-BLOOD anchor. The worthiness (axios) is HYPER-CREATURELY: only the divine-incarnate could redeem the cosmos. The ēgorasas (purchased / redeemed) is commercial-language: the Word&#x27;s-blood is the redemption-price. The ek pasēs phylēs kai glōssēs (out of every tribe and tongue) marks the cosmic-scope: the redemption is for all-humanity, not Israel-only. Tewahedo Anaphora cites Rev 5:9 at the Communion-distribution as the universal-redemption-by-blood acclamation.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
